import React, { useState, useEffect } from 'react';
import { Edit3, CheckCircle, Zap, User, BookOpen, Code, Target, Award, Camera, Activity, Eye, Network, MapPin, Briefcase } from 'lucide-react';

const skillOptions = ['React', 'Python', 'Java', 'Machine Learning', 'SQL', 'Node.js', 'Data Analysis', 'Product Management', 'UI/UX Design', 'System Design', 'AWS', 'Docker'];
const interestOptions = ['FinTech', 'Product Management', 'Data Science', 'Software Engineering', 'AI/ML', 'Consulting', 'Design', 'DevOps', 'Research', 'Entrepreneurship'];
const societyOptions = ['None', 'UCS - University Coding Society', 'UDT - University Design Team', 'ULC - University Literary Club'];

const generateBio = async (name, branch, year, skills, interests) => {
  await new Promise(r => setTimeout(r, 1800));
  return `I'm ${name}, a ${year} ${branch.includes('Batch') ? 'graduate' : 'student'} with a strong foundation in ${skills.slice(0, 2).join(' and ')}. I'm passionate about building innovative solutions at the intersection of technology and ${interests[0] || 'business'}. Exploring opportunities in ${interests.slice(0, 2).join(' and ')}, I thrive in collaborative environments where I can apply my analytical thinking to real-world problems.`;
};

export default function Profile({ role, user, setUser }) {
  const [editing, setEditing] = useState(false);
  const [name, setName] = useState(user?.name || (role === 'alumni' ? 'Alumni User' : 'Student User'));
  const [branch, setBranch] = useState(user?.branch || 'B.Tech Computer Science Engineering');
  const [year, setYear] = useState(user?.year || (role === 'alumni' ? 'Batch 2020' : '3rd Year'));
  const [bio, setBio] = useState(user?.bio || (role === 'alumni'
    ? `${user?.role_title || 'Professional'} at ${user?.company || 'Company'}. Passionate about mentoring students from my alma mater.`
    : 'Add your bio or generate one using AI below.'));
  const [skills, setSkills] = useState(user?.skills || ['React', 'Python', 'SQL']);
  const [interests, setInterests] = useState(user?.interests || ['Product Management', 'FinTech']);
  const [society, setSociety] = useState(user?.society || 'None');
  const [generating, setGenerating] = useState(false);
  const [saved, setSaved] = useState(false);
  const [visible, setVisible] = useState(false);
  useEffect(() => { setTimeout(() => setVisible(true), 100); }, []);

  const handleGenBio = async () => {
    setGenerating(true);
    setBio(await generateBio(name, branch, year, skills, interests));
    setGenerating(false);
  };

  const handleSave = () => {
    setEditing(false); setSaved(true);
    if (setUser) setUser(prev => ({ ...prev, name, branch, year, bio, skills, interests, society }));
    setTimeout(() => setSaved(false), 3000);
  };

  const toggleSkill = s => setSkills(p => p.includes(s) ? p.filter(x => x !== s) : [...p, s]);
  const toggleInterest = i => setInterests(p => p.includes(i) ? p.filter(x => x !== i) : [...p, i]);
  const completion = Math.min(100, [name, branch, year, bio.length > 50, skills.length > 0, interests.length > 0, society !== 'None'].filter(Boolean).length * 14);

  return (
    <div style={{ padding: '40px 40px 80px', maxWidth: 1200, margin: '0 auto', opacity: visible ? 1 : 0, transform: visible ? 'none' : 'translateY(20px)', transition: 'all 0.6s ease' }}>
      
      {/* Header */}
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 40 }}>
        <div>
          <h1 style={{ fontFamily: 'var(--font-display)', fontSize: 36, fontWeight: 800, color: 'var(--white)', marginBottom: 8, display: 'flex', alignItems: 'center', gap: 12 }}>
            My Bento Profile <span style={{ padding: '4px 10px', background: 'rgba(245,166,35,0.15)', color: 'var(--gold)', fontSize: 12, borderRadius: 20, fontWeight: 700 }}>NEW</span>
          </h1>
          <p style={{ color: 'var(--text-secondary)' }}>A modern snapshot of your professional journey.</p>
        </div>
        <div style={{ display: 'flex', gap: 12 }}>
          {saved && (
            <div style={{ display: 'flex', alignItems: 'center', gap: 8, padding: '10px 18px', borderRadius: 12, background: 'rgba(34,212,94,0.1)', color: 'var(--success)', fontSize: 14, fontWeight: 700 }}>
              <CheckCircle size={16} /> Saved!
            </div>
          )}
          <button onClick={() => editing ? handleSave() : setEditing(true)} style={{ display: 'flex', alignItems: 'center', gap: 8, padding: '12px 24px', borderRadius: 16, background: editing ? 'linear-gradient(135deg, var(--gold), #e8880a)' : 'var(--navy-card)', color: editing ? '#07091a' : 'var(--white)', fontWeight: 700, fontSize: 14, border: editing ? 'none' : '1px solid rgba(255,255,255,0.1)', transition: 'all 0.2s', cursor: 'pointer', boxShadow: editing ? '0 8px 25px rgba(245,166,35,0.3)' : 'none' }}>
            {editing ? <><CheckCircle size={16} /> Save Profile</> : <><Edit3 size={16} /> Edit Profile</>}
          </button>
        </div>
      </div>

      {/* === BENTO BOX GRID === */}
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(12, 1fr)', gap: 24, autoRows: 'minmax(200px, auto)' }}>
        
        {/* CARD 1: Identity (Span 4 cols, 2 rows) */}
        <div style={{ gridColumn: 'span 4', gridRow: 'span 2', background: 'var(--navy-card)', borderRadius: 32, padding: 32, display: 'flex', flexDirection: 'column', alignItems: 'center', textAlign: 'center', border: '1px solid rgba(255,255,255,0.05)', position: 'relative', overflow: 'hidden' }}>
          <div style={{ position: 'absolute', top: 0, left: 0, right: 0, height: 120, background: 'linear-gradient(135deg, rgba(245,166,35,0.2), rgba(77,166,255,0.1))', zIndex: 0 }} />
          
          <div style={{ width: 140, height: 140, borderRadius: '50%', background: 'linear-gradient(135deg, var(--gold), #e8880a)', display: 'flex', alignItems: 'center', justifyContent: 'center', fontFamily: 'var(--font-display)', fontWeight: 800, fontSize: 56, color: '#07091a', border: '8px solid var(--navy-card)', boxShadow: '0 10px 40px rgba(245,166,35,0.3)', position: 'relative', zIndex: 1, marginTop: 40, marginBottom: 20 }}>
            {name[0]?.toUpperCase()}
            {editing && (
              <div style={{ position: 'absolute', bottom: 0, right: 10, width: 36, height: 36, borderRadius: '50%', background: 'var(--navy)', border: '2px solid var(--gold)', display: 'flex', alignItems: 'center', justifyContent: 'center', cursor: 'pointer' }}>
                <Camera size={16} color="var(--gold)" />
              </div>
            )}
          </div>

          <div style={{ zIndex: 1, width: '100%' }}>
            {editing ? (
              <input value={name} onChange={e => setName(e.target.value)} style={{ width: '100%', padding: '10px', borderRadius: 12, border: '1px solid var(--gold-border)', background: 'var(--navy-2)', color: 'var(--white)', fontSize: 24, fontWeight: 800, textAlign: 'center', outline: 'none', fontFamily: 'var(--font-display)', marginBottom: 12 }} />
            ) : (
              <h2 style={{ fontFamily: 'var(--font-display)', fontSize: 28, fontWeight: 800, color: 'var(--white)', marginBottom: 4 }}>{name}</h2>
            )}
            
            <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 6, color: 'var(--gold)', fontSize: 13, fontWeight: 700, textTransform: 'uppercase', letterSpacing: 1, marginBottom: 16 }}>
              <Briefcase size={14} /> {role === 'alumni' ? 'Alumni' : 'Student'}
            </div>

            <div style={{ background: 'var(--navy-2)', borderRadius: 16, padding: 16, width: '100%', border: '1px solid rgba(255,255,255,0.03)' }}>
              <div style={{ marginBottom: 10 }}>
                {editing ? <input value={branch} onChange={e => setBranch(e.target.value)} style={{ width: '100%', padding: '8px', borderRadius: 8, border: '1px solid rgba(255,255,255,0.1)', background: 'var(--navy)', color: 'var(--text-primary)', fontSize: 13, textAlign: 'center', outline: 'none' }} />
                  : <div style={{ fontSize: 13, color: 'var(--text-secondary)', fontWeight: 500 }}>{branch}</div>}
              </div>
              <div>
                {editing ? <input value={year} onChange={e => setYear(e.target.value)} style={{ width: '100%', padding: '8px', borderRadius: 8, border: '1px solid rgba(255,255,255,0.1)', background: 'var(--navy)', color: 'var(--text-primary)', fontSize: 13, textAlign: 'center', outline: 'none' }} />
                  : <div style={{ fontSize: 13, color: 'var(--text-secondary)', fontWeight: 500 }}>{year}</div>}
              </div>
            </div>
          </div>
        </div>

        {/* CARD 2: Bio (Span 8 cols, 1 row) */}
        <div style={{ gridColumn: 'span 8', gridRow: 'span 1', background: 'var(--navy-card)', borderRadius: 32, padding: 32, border: generating ? '1px solid var(--gold)' : '1px solid rgba(255,255,255,0.05)', boxShadow: generating ? '0 0 40px rgba(245,166,35,0.15)' : 'none', transition: 'all 0.3s' }}>
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 20 }}>
            <h3 style={{ fontFamily: 'var(--font-display)', fontSize: 20, fontWeight: 800, color: 'var(--white)', display: 'flex', alignItems: 'center', gap: 10 }}>
              <BookOpen size={20} color="var(--gold)" /> My Story
            </h3>
            <button onClick={handleGenBio} disabled={generating} style={{ display: 'flex', alignItems: 'center', gap: 8, padding: '8px 16px', borderRadius: 12, border: '1px solid rgba(245,166,35,0.3)', background: 'rgba(245,166,35,0.1)', color: 'var(--gold)', fontSize: 13, fontWeight: 700, opacity: generating ? 0.7 : 1, cursor: generating ? 'not-allowed' : 'pointer' }}>
              <Zap size={14} /> {generating ? 'AI Writing...' : 'AI Rewrite'}
            </button>
          </div>

          {generating ? (
            <div style={{ padding: 20 }}>
              <div style={{ height: 14, background: 'linear-gradient(90deg, var(--navy-3), var(--gold-dim), var(--navy-3))', backgroundSize: '200% 100%', animation: 'shimmer 1.5s infinite', borderRadius: 8, marginBottom: 12 }} />
              <div style={{ height: 14, background: 'linear-gradient(90deg, var(--navy-3), var(--gold-dim), var(--navy-3))', backgroundSize: '200% 100%', animation: 'shimmer 1.5s infinite 0.2s', borderRadius: 8, width: '90%', marginBottom: 12 }} />
              <div style={{ height: 14, background: 'linear-gradient(90deg, var(--navy-3), var(--gold-dim), var(--navy-3))', backgroundSize: '200% 100%', animation: 'shimmer 1.5s infinite 0.4s', borderRadius: 8, width: '70%' }} />
            </div>
          ) : editing ? (
            <textarea value={bio} onChange={e => setBio(e.target.value)} rows={4} style={{ width: '100%', padding: '16px', borderRadius: 16, border: '1px solid rgba(255,255,255,0.1)', background: 'var(--navy-2)', color: 'var(--text-primary)', fontSize: 16, outline: 'none', lineHeight: 1.6, resize: 'vertical' }} />
          ) : (
            <p style={{ fontSize: 16, color: 'var(--text-secondary)', lineHeight: 1.7, margin: 0 }}>{bio}</p>
          )}
        </div>

        {/* CARD 3: Top Skills (Span 4 cols, 1 row) */}
        <div style={{ gridColumn: 'span 4', gridRow: 'span 1', background: 'var(--navy-card)', borderRadius: 32, padding: 32, border: '1px solid rgba(255,255,255,0.05)', display: 'flex', flexDirection: 'column' }}>
          <h3 style={{ fontFamily: 'var(--font-display)', fontSize: 20, fontWeight: 800, color: 'var(--white)', marginBottom: 20, display: 'flex', alignItems: 'center', gap: 10 }}>
            <Code size={20} color="#4da6ff" /> Tech Arsenal
          </h3>
          <div style={{ display: 'flex', gap: 10, flexWrap: 'wrap', flex: 1, alignContent: 'flex-start' }}>
            {skillOptions.slice(0, 8).map(s => {
              const active = skills.includes(s);
              if (!editing && !active) return null;
              return (
                <button key={s} onClick={() => editing && toggleSkill(s)} style={{ padding: '8px 14px', borderRadius: 12, border: active ? 'none' : '1px dashed rgba(255,255,255,0.2)', background: active ? 'rgba(77,166,255,0.15)' : 'transparent', color: active ? '#4da6ff' : 'var(--text-muted)', fontSize: 13, fontWeight: active ? 700 : 500, cursor: editing ? 'pointer' : 'default' }}>
                  {active ? s : `+ ${s}`}
                </button>
              );
            })}
          </div>
        </div>

        {/* CARD 4: Interests (Span 4 cols, 1 row) */}
        <div style={{ gridColumn: 'span 4', gridRow: 'span 1', background: 'var(--navy-card)', borderRadius: 32, padding: 32, border: '1px solid rgba(255,255,255,0.05)', display: 'flex', flexDirection: 'column' }}>
          <h3 style={{ fontFamily: 'var(--font-display)', fontSize: 20, fontWeight: 800, color: 'var(--white)', marginBottom: 20, display: 'flex', alignItems: 'center', gap: 10 }}>
            <Target size={20} color="#a78bfa" /> Pursuits
          </h3>
          <div style={{ display: 'flex', gap: 10, flexWrap: 'wrap', flex: 1, alignContent: 'flex-start' }}>
            {interestOptions.slice(0, 6).map(i => {
              const active = interests.includes(i);
              if (!editing && !active) return null;
              return (
                <button key={i} onClick={() => editing && toggleInterest(i)} style={{ padding: '8px 14px', borderRadius: 12, border: active ? 'none' : '1px dashed rgba(255,255,255,0.2)', background: active ? 'rgba(168,139,250,0.15)' : 'transparent', color: active ? '#a78bfa' : 'var(--text-muted)', fontSize: 13, fontWeight: active ? 700 : 500, cursor: editing ? 'pointer' : 'default' }}>
                  {active ? i : `+ ${i}`}
                </button>
              );
            })}
          </div>
        </div>

        {/* CARD 5: Completion & Stats (Span 8 cols, 1 row) */}
        <div style={{ gridColumn: 'span 8', gridRow: 'span 1', background: 'linear-gradient(135deg, rgba(245,166,35,0.08), rgba(0,0,0,0.2))', borderRadius: 32, padding: 32, border: '1px solid rgba(245,166,35,0.2)', display: 'flex', gap: 40, alignItems: 'center' }}>
          
          <div style={{ flex: 1 }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: 12 }}>
              <span style={{ fontWeight: 700, color: 'var(--white)', fontSize: 16 }}>Profile Strength</span>
              <span style={{ fontWeight: 800, color: 'var(--gold)', fontSize: 18 }}>{completion}%</span>
            </div>
            <div style={{ height: 12, background: 'rgba(0,0,0,0.3)', borderRadius: 6, marginBottom: 16, border: '1px solid rgba(255,255,255,0.05)' }}>
              <div style={{ width: `${completion}%`, height: '100%', background: 'linear-gradient(90deg, var(--gold), #ffc55a)', borderRadius: 6, transition: 'width 0.5s ease', boxShadow: '0 0 15px rgba(245,166,35,0.4)' }} />
            </div>
            <p style={{ fontSize: 13, color: 'var(--text-secondary)', margin: 0 }}>You're highly visible to mentors and recruiters.</p>
          </div>

          <div style={{ width: 1, height: '80%', background: 'rgba(255,255,255,0.1)' }} />

          <div style={{ display: 'flex', gap: 32 }}>
            <div>
              <div style={{ fontSize: 13, color: 'var(--text-muted)', marginBottom: 4, display: 'flex', alignItems: 'center', gap: 6 }}><Eye size={14} /> Views</div>
              <div style={{ fontSize: 32, fontFamily: 'var(--font-display)', fontWeight: 800, color: 'var(--white)' }}>142</div>
            </div>
            <div>
              <div style={{ fontSize: 13, color: 'var(--text-muted)', marginBottom: 4, display: 'flex', alignItems: 'center', gap: 6 }}><Network size={14} /> Network</div>
              <div style={{ fontSize: 32, fontFamily: 'var(--font-display)', fontWeight: 800, color: 'var(--white)' }}>28</div>
            </div>
          </div>

        </div>

        {/* CARD 6: Society (Span 4 cols, 1 row) */}
        <div style={{ gridColumn: 'span 4', gridRow: 'span 1', background: 'var(--navy-card)', borderRadius: 32, padding: 32, border: '1px solid rgba(255,255,255,0.05)', display: 'flex', flexDirection: 'column', justifyContent: 'center' }}>
          <h3 style={{ fontFamily: 'var(--font-display)', fontSize: 20, fontWeight: 800, color: 'var(--white)', marginBottom: 20, display: 'flex', alignItems: 'center', gap: 10 }}>
            <Award size={20} color="#fb923c" /> Affiliation
          </h3>
          {editing ? (
            <select value={society} onChange={e => setSociety(e.target.value)} style={{ width: '100%', padding: '14px', borderRadius: 12, border: '1px solid rgba(255,255,255,0.1)', background: 'var(--navy-2)', color: 'var(--text-primary)', fontSize: 14, outline: 'none', cursor: 'pointer' }}>
              {societyOptions.map(s => <option key={s} value={s}>{s}</option>)}
            </select>
          ) : (
            <div style={{ padding: '20px', background: society !== 'None' ? 'rgba(251,146,60,0.1)' : 'rgba(255,255,255,0.03)', border: `1px solid ${society !== 'None' ? 'rgba(251,146,60,0.3)' : 'rgba(255,255,255,0.05)'}`, borderRadius: 16, color: society !== 'None' ? '#fb923c' : 'var(--text-muted)', fontSize: 15, fontWeight: 700, display: 'flex', alignItems: 'center', gap: 12 }}>
              {society !== 'None' ? '🏆' : '📍'} {society === 'None' ? 'Not part of any society' : society}
            </div>
          )}
        </div>

      </div>
    </div>
  );
}
